recoverFromError(error, vnode, oldVNode, errorInfo) {
	const errorDesc = this.describeError(error, vnode, errorInfo);
	error = errorDesc.error;

	this.lastCaughtError = error;
	this.errorBoundaryTarget = null;
	this.errorTrail = [];
	this.recordCaughtError(error);
	this.resetErrorTrail();
	errorInfo = this.normalizeErrorInfo(errorInfo);
	this.describeErrorPath(vnode, oldVNode);
	let component, ctor, handled;
	for (; (vnode = vnode._parent); ) {
		this.noteErrorAncestor(vnode);
		if ((component = vnode._component) && !component._processingException) {
